const experiences={first:{title:'Todo surfista<br>já foi iniciante.',level:'PARA QUEM VAI COMEÇAR',number:'/ 01',tag:'SEU PRIMEIRO DROP COMEÇA AQUI',image:'assets/session.jpg',alt:'Grupo com pranchas de surf na água',description:'Conheça a prancha, sinta o movimento da água e descubra a alegria de ficar em pé pela primeira vez. Sem cobrança. Com orientação a cada remada.',duration:'Uma manhã, sem pressa',focus:'Base, remada e primeiras ondas',vibe:'Turma pequena, grandes descobertas',name:'Primeira onda'},flow:{title:'Menos pensar.<br>Mais sentir.',level:'PARA QUEM QUER EVOLUIR',number:'/ 02',tag:'SUA PRÓXIMA ONDA É DIFERENTE',image:'assets/ocean.jpg',alt:'Surfista em pé deslizando pela onda',description:'Ajuste sua leitura do mar, encontre o melhor posicionamento e ganhe fluidez. Uma experiência para quem já pega ondas e quer construir mais confiança no próprio surf.',duration:'Uma sessão no seu ritmo',focus:'Posicionamento, linha e fluidez',vibe:'Atenção aos detalhes, liberdade no surf',name:'Encontre o flow'},free:{title:'O melhor plano?<br>Estar lá fora.',level:'PARA QUEM QUER SE CONECTAR',number:'/ 03',tag:'BOAS HISTÓRIAS VÊM DE DIAS ASSIM',image:'assets/island.webp',alt:'Paisagem costeira com coqueiros e skatista',description:'Um encontro com o lado simples da vida: praia, movimento e boas conversas. A cultura do surf em um dia para respirar, conhecer gente e deixar o relógio um pouco de lado.',duration:'Um dia para desconectar',focus:'Praia, movimento e convivência',vibe:'Sol, ar livre e gente boa',name:'Dia de mar'}};
let selected='first';const tabs=[...document.querySelectorAll('[role="tab"]')];
function setExperience(key){selected=key;const data=experiences[key];tabs.forEach(tab=>{const active=tab.dataset.experience===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1});document.getElementById('experience-panel').setAttribute('aria-labelledby','tab-'+key);document.getElementById('experience-title').innerHTML=data.title;['level','number','tag','description','duration','focus','vibe'].forEach(field=>document.getElementById('experience-'+field).textContent=data[field]);const img=document.getElementById('experience-img');img.src=data.image;img.alt=data.alt;document.getElementById('level')&&(document.getElementById('level').value=key)}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>setExperience(tab.dataset.experience));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();setExperience(tabs[next].dataset.experience)}})});
const menu=document.querySelector('.menu-toggle'),navigation=document.getElementById('navigation');function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');navigation.classList.remove('open')}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');navigation.classList.toggle('open',open)});navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus()}});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const config=window.SURF_CONFIG;
const rates=[40,40,50,50,60,55];
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const rental=document.querySelector('[data-kind="Aluguel"]');
function rentalTotal(){if(!rental)return;const plan=document.getElementById('rental-plan').value;const qty=document.getElementById('rental-qty');const people=Number(document.getElementById('rental-people').value);document.getElementById('quantity-label').textContent=plan==='hour'?'Horas':plan==='day'?'Diárias':'Passes de fim de semana';const rate=plan==='hour'?rates[Number(document.getElementById('rental-board').value)]:plan==='day'?120:250;const valid=rental.querySelectorAll('input[type="number"]');document.getElementById('rental-total').textContent=[...valid].every(x=>x.checkValidity())?'Estimativa: '+money(rate*Number(qty.value)*people):'Informe quantidades válidas.';}
rental?.addEventListener('input',rentalTotal);rentalTotal();
document.querySelectorAll('.pick-board').forEach(b=>b.addEventListener('click',()=>{document.getElementById('rental-board').value=b.dataset.board;rentalTotal();document.getElementById('simulador').scrollIntoView({behavior:'smooth'});document.getElementById('rental-board').focus({preventScroll:true});}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.product').forEach(x=>x.hidden=!(b.dataset.filter==='Todos'||x.dataset.condition===b.dataset.filter||(b.dataset.filter==='Acessórios'&&x.dataset.accessory==='true')));}));
document.querySelectorAll('.pick-product').forEach(b=>b.addEventListener('click',()=>{document.getElementById('shop-product').value=b.dataset.product;document.getElementById('compra').scrollIntoView({behavior:'smooth'});document.getElementById('shop-product').focus({preventScroll:true});}));
const today=new Date();const minDate=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');document.querySelectorAll('input[type="date"]').forEach(x=>x.min=minDate);
document.querySelectorAll('.order-form').forEach(form=>{form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const lines=['Olá, Expresso Local! Gostaria de consultar: '+form.dataset.kind];for(const el of form.elements){if(!el.name||el.type==='submit')continue;if(el.type==='checkbox'&&!el.checked)continue;const value=el.tagName==='SELECT'?el.selectedOptions[0].textContent:el.value;if(value)lines.push(el.name+': '+value);}if(form===rental)lines.push(document.getElementById('rental-total').textContent+' (adicionais e disponibilidade a confirmar)');const box=form.querySelector('.order-result');const message=lines.join('\n');box.querySelector('textarea').value=message;const a=box.querySelector('.send-order');if(/^\d{10,15}$/.test(config.whatsapp)){a.href='https://wa.me/'+config.whatsapp+'?text='+encodeURIComponent(message);a.textContent='Enviar pelo WhatsApp';box.querySelector('.order-status').textContent='A reserva será confirmada pela equipe.';}else{a.href=config.instagram;a.textContent='Abrir Instagram da escola';box.querySelector('.order-status').textContent='Copie o pedido e envie por mensagem para @tribo_local. O WhatsApp da escola será disponibilizado em breve.';}box.hidden=false;box.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});form.querySelector('.copy-order').addEventListener('click',async()=>{const t=form.querySelector('.order-result textarea');try{await navigator.clipboard.writeText(t.value);form.querySelector('.order-status').textContent='Pedido copiado. Envie para a equipe confirmar.';}catch{t.focus();t.select();form.querySelector('.order-status').textContent='Selecione e copie o pedido acima.';}});});
document.querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>{const c=document.querySelector('.team-carousel');c.scrollBy({left:Number(b.dataset.slide)*(c.querySelector('article').getBoundingClientRect().width+24),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
const current=location.pathname.split('/').pop()||'index.html';document.querySelectorAll('#navigation a').forEach(a=>{if(a.getAttribute('href')===current)a.setAttribute('aria-current','page');});
